/**
 * components/shared/InvoicePreviewModal.js: on-screen invoice preview + download.
 *
 * Shows the HTML twin of the invoice and offers the PDF: the stored issued_invoice
 * (with version history) when one exists, otherwise a live PDFDownloadLink. The
 * HTML preview is fed by the same utils/invoicePdfModel.js fetch the stored-PDF
 * generator uses, and reuses InvoicePDF.js's helpers, so preview and saved file
 * can never diverge.
 *
 * @invariant render InvoicePDF only through this modal or the generator; never
 *            add a second invoice template. @see components/shared/pdf/InvoicePDF.js
 * @gotcha live download requires an assigned invoice_number (campaign complete);
 *         otherwise the button is disabled.
 * @gotcha a REFUSED invoice_documents read is not "no stored PDF". The live link is withheld
 *         too, because a fresh render is not the document the agency was sent.
 */
import React, { useState, useEffect } from 'react';
import { PDFDownloadLink } from '@react-pdf/renderer';
import { fmtDate, fmtMoney, isInKind } from '../../utils/format';
import { loadCurrentDoc, loadVersionHistory } from '../../utils/invoiceDocuments';
import { downloadStoredFile } from '../../utils/storage';
import { fetchInvoicePdfData } from '../../utils/invoicePdfModel';
import {
  InvoicePDF, buildInvoiceFields, truncate,
  fmtAddrDetail, fmtAddrLines, fmtLineItemSub,
} from './pdf/InvoicePDF';
import Feedback from './Feedback';
import ReadError from './ReadError';
import Loading from './Loading';
import { humanizeError } from '../../utils/errors';
import { useModalA11y } from '../../hooks/useModalA11y';

// ── Modal ─────────────────────────────────────────────────────────────────────
export default function InvoicePreviewModal({ row, invoice, onClose }) {
  // No `.modal-header` to label, so it holds the hook directly rather than <Modal>.
  const { overlayRef, dialogRef } = useModalA11y(onClose);
  const [data,    setData]    = useState(null);
  const [loading, setLoading] = useState(true);
  const [loadErr, setLoadErr] = useState(null);
  const [storedDoc, setStoredDoc] = useState(null);   // current issued_invoice
  const [storedErr, setStoredErr] = useState(null);   // refused invoice_documents read
  const [versions, setVersions]   = useState([]);     // all versions for this invoice
  const [showVersions, setShowVersions] = useState(false);

  useEffect(() => {
    let alive = true;
    (async () => {
      // Same shared fetch the stored-PDF generator uses, so the live
      // preview and the saved file can never diverge.
      // fetchInvoicePdfData THROWS when any field the document prints could not
      // be read. Before W-48b it returned partial data and this modal rendered
      // an invoice with a blank Bill To or no line items, which is also exactly
      // what the stored PDF would have been generated from.
      try {
        const d = await fetchInvoicePdfData({
          campaignId: row.campaign_id,
          creatorProfileId: row.creator_profile_id,
        });
        if (!alive) return;
        setData(d);
      } catch (e) {
        if (!alive) return;
        setLoadErr(humanizeError(e));
      }
      setLoading(false);
    })();
    return () => { alive = false; };
  }, [row.creator_profile_id, row.campaign_id]);

  // Load the stored issued_invoice document + its full version history.
  useEffect(() => {
    let alive = true;
    if (!invoice?.id) { setStoredDoc(null); setStoredErr(null); setVersions([]); return; }
    (async () => {
      const [cur, hist] = await Promise.all([
        loadCurrentDoc(invoice.id, 'issued_invoice'),
        loadVersionHistory(invoice.id),
      ]);
      if (!alive) return;
      setStoredDoc(cur.doc);
      // A refused read is not proof there is no stored PDF. Unbound, it fell through to the
      // live PDFDownloadLink below, so a document nobody could read was replaced on screen by
      // a FRESH render under the button that reads as THE download. The history read is folded
      // in here because the same refusal empties `versions` and takes its control with it.
      // @see utils/invoiceDocuments.js loadCurrentDoc
      setStoredErr(cur.error || hist.error || null);
      setVersions(hist.rows.filter(d => d.doc_type === 'issued_invoice'));
    })();
    return () => { alive = false; };
  }, [invoice?.id]);

  const inKind           = isInKind(invoice?.is_in_kind);
  const hasInvoiceNumber = !!invoice?.invoice_number;
  const invoiceNumber    = invoice?.invoice_number || '—';
  const agencyName       = !loading && data ? (data.agency?.name || 'Agency') : 'Agency';
  const agencySlug       = agencyName.replace(/[^a-z0-9]/gi, '-');
  const fileName         = inKind
    ? `InKind-Record${hasInvoiceNumber ? `-${invoiceNumber}` : ''}-${agencySlug}.pdf`
    : `Invoice-${invoiceNumber}-${agencySlug}.pdf`;

  return (
    <div className="modal-overlay invoice-preview-overlay" ref={overlayRef}>
      <div
        className="invoice-preview-shell"
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-label={inKind ? 'In-kind record preview' : 'Invoice preview'}
        tabIndex={-1}
      >

        <div className="invoice-preview-toolbar">
          <div className="invoice-preview-toolbar-meta">
            {hasInvoiceNumber ? (
              <>
                <span className="invoice-preview-toolbar-number">{inKind ? 'In-Kind Record' : 'Invoice'} {invoiceNumber}</span>
                <span className="invoice-preview-toolbar-sep">·</span>
                <span className="invoice-preview-toolbar-agency">{agencyName}</span>
              </>
            ) : (
              <span className="invoice-preview-toolbar-draft">{inKind ? 'In-kind compensation record' : 'No invoice number: campaign not yet completed'}</span>
            )}
          </div>
          <div className="invoice-preview-toolbar-actions">
            <button className="btn btn-ghost btn-sm" onClick={onClose}>Close</button>
            {versions.length > 1 ? (
              <button className="btn btn-ghost btn-sm" onClick={() => setShowVersions(v => !v)}>
                {showVersions ? 'Hide versions' : `Versions (${versions.length})`}
              </button>
            ) : null}
            {storedDoc?.signedUrl ? (
              // A button, not an anchor. The anchor said Download and OPENED the PDF in a tab,
              // which is the P46 defect: the label promised a save the control never made.
              <button type="button" className="btn btn-primary btn-sm"
                onClick={() => downloadStoredFile(storedDoc.bucket, storedDoc.file_path, fileName)}>
                ↓ Download stored PDF (v{storedDoc.version})
              </button>
            ) : !storedErr && !loading && data && hasInvoiceNumber ? (
              <PDFDownloadLink
                document={<InvoicePDF row={row} invoice={invoice} data={data} />}
                fileName={fileName}
                className="btn btn-primary btn-sm"
                style={{ textDecoration: 'none' }}
              >
                {({ loading: pdfLoading, error }) => {
                  if (error) { if (process.env.NODE_ENV !== 'production') console.error('PDF generation error:', error); return 'PDF Error'; }
                  return pdfLoading ? 'Generating…' : `↓ Download ${inKind ? 'Record' : 'PDF'} (live)`;
                }}
              </PDFDownloadLink>
            ) : (
              <button className="btn btn-primary btn-sm" disabled>↓ Download PDF</button>
            )}
          </div>
        </div>

        {/* Between the sticky toolbar and the versions strip, copying that strip's own style:
            a .feedback block inside .invoice-preview-toolbar-actions would roughly double the
            height of a toolbar that is position: sticky. */}
        {storedErr ? (
          <div style={{ padding: '10px 16px', background: 'rgba(255,255,255,0.04)', borderBottom: '1px solid var(--border)' }}>
            <ReadError error={storedErr} />
          </div>
        ) : null}

        {showVersions ? (
          <div style={{ padding: '10px 16px', background: 'rgba(255,255,255,0.04)', borderBottom: '1px solid var(--border)' }}>
            <div style={{ fontSize: 11, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: 1, marginBottom: 6 }}>Stored versions</div>
            <ul style={{ listStyle: 'none', margin: 0, padding: 0, display: 'flex', flexDirection: 'column', gap: 4 }}>
              {versions.map(v => (
                <li key={v.id} style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, padding: '4px 0' }}>
                  <span>
                    <strong>v{v.version}</strong>{v.is_current ? ' (current)' : ''}
                    <span style={{ color: 'var(--muted)', marginLeft: 8 }}>{fmtDate(v.generated_at)}</span>
                  </span>
                  {v.signedUrl ? (
                    <button type="button" className="link" style={{ color: 'var(--blue)' }}
                      aria-label={`Download version ${v.version}`}
                      onClick={() => downloadStoredFile(v.bucket, v.file_path, fileName.replace(/\.pdf$/, `-v${v.version}.pdf`))}>↓ download</button>
                  ) : null}
                </li>
              ))}
            </ul>
          </div>
        ) : null}

        {loading ? (
          <Loading className="invoice-preview-loading">Loading invoice data…</Loading>
        ) : loadErr ? (
          <Feedback value={loadErr} />
        ) : (
          <InvoicePreview row={row} invoice={invoice} data={data} hasInvoiceNumber={hasInvoiceNumber} />
        )}

      </div>
    </div>
  );
}

// ── HTML preview ──────────────────────────────────────────────────────────────
/**
 * The HTML twin of InvoicePDF, computing identical content from InvoicePDF.js's
 * shared helpers (line items, terms, addresses) so the screen matches the PDF.
 */
function InvoicePreview({ row, invoice, data, hasInvoiceNumber }) {
  const {
    agency, sender, platformAccts,
    inKind, invoiceDate, dueDate, amount, inKindDesc,
    amountPaid, balanceDue, billToName, billToContact, billToAddr,
    fromName, fromAddr, campaignName, serviceDesc, websiteDisplay,
    lineItems, termLines, dedupedAddrs,
  } = buildInvoiceFields({ row, invoice, data });

  // The placeholder is the PREVIEW's, not the document's: a draft with no number
  // yet reads as blank on screen, and a stored PDF must never print a dash where
  // its number goes. @see components/shared/pdf/InvoicePDF.js buildInvoiceFields
  const invoiceNumber = invoice?.invoice_number || '—';

  const hdrMetaRight = [
    invoice?.invoice_number ? `No. ${invoiceNumber}` : null,
    invoiceDate ? `Issued ${fmtDate(invoiceDate)}` : null,
    'Page 1 of 1',
  ].filter(Boolean).join('  ·  ');

  // Build remit columns matching template layout. dedupedAddrs comes from
  // buildInvoiceFields, so the two surfaces cannot dedupe differently, and it is already
  // the SNAPSHOT for an invoice that has one. No fail-open branch at the bottom.
  const paypalAddr   = dedupedAddrs.find(a => /paypal/i.test(a.method));
  const otherAddrs   = dedupedAddrs.filter(a => !/paypal/i.test(a.method));
  let paypalLine = paypalAddr ? fmtAddrDetail(paypalAddr) : '';
  const paypalLabel2 = paypalAddr?.is_preferred ? 'PayPal (preferred)' : 'PayPal';
  const otherMethodLabel2 = [...new Set(otherAddrs.map(a => a.method))].join(' / ')
    + (otherAddrs.some(a => a.is_preferred) ? ' (preferred)' : '');
  const multiMethod2 = new Set(otherAddrs.map(a => a.method)).size > 1;
  let achLines = otherAddrs.length > 0
    ? otherAddrs.flatMap(a => {
        const lines = fmtAddrLines(a);
        return multiMethod2 ? [`${a.method}: ${lines[0]}`, ...lines.slice(1)] : lines;
      }).join('\n')
    : null;
  if (!paypalLine && !achLines && sender?.email) paypalLine = sender.email;

  return (
    <div className={`invoice-doc${!hasInvoiceNumber ? ' invoice-doc-draft' : ''}`}>

      {!hasInvoiceNumber && (
        <div className="invoice-doc-no-number-banner">
          Invoice number will be assigned automatically when the campaign is marked complete.
        </div>
      )}

      {/* Header */}
      <div className="header-band">
        <div className="header-top">
          <div className="wordmark">NYS<span className="dot">T</span>ERYS</div>
          <div className="invoice-label">{inKind ? 'IN-KIND RECORD' : 'INVOICE'}</div>
        </div>
        <div className="header-divider" />
        <div className="header-meta">
          <span>Creator Management &nbsp;·&nbsp; Brand Partnerships</span>
          <span>{hdrMetaRight}</span>
        </div>
      </div>

      {/* Body */}
      <div className="inv-body">

        {/* From / Bill To */}
        <div className="addresses">
          <div>
            <div className="addr-label">FROM</div>
            <div className="addr-name">{fromName}</div>
            {fromAddr.map((l, i) => <div key={i} className="addr-line">{l}</div>)}
            {sender?.email  && <div className="addr-line addr-line-spaced">{sender.email}</div>}
            {sender?.tax_id && <div className="addr-line addr-line-spaced">EIN: {sender.tax_id}</div>}
            {!sender && <div className="addr-line" style={{ color: 'var(--red)' }}>Configure in Setup → Business Profile</div>}
          </div>
          <div>
            <div className="addr-label">BILL TO</div>
            {billToName    && <div className="addr-name">{billToName}</div>}
            {billToContact && <div className="addr-line">{billToContact}</div>}
            {billToAddr.map((l, i) => <div key={i} className="addr-line">{l}</div>)}
            {!billToAddr.length && agency.email && <div className="addr-line addr-line-spaced">{agency.email}</div>}
            {agency.company_reg_number && <div className="addr-line addr-line-spaced">Reg: {agency.company_reg_number}</div>}
            {agency.vat_number         && <div className="addr-line addr-line-spaced">VAT: {agency.vat_number}</div>}
          </div>
        </div>

        {/* Amount Due / FMV callout */}
        <div className="due-callout">
          <div>
            <div className="due-label">{inKind ? 'Fair Market Value' : 'Amount Due'}</div>
            <div className="due-amount">{fmtMoney(amount)}</div>
          </div>
          <div>
            <div className="due-label" style={{ textAlign: 'right' }}>{inKind ? 'Date Received' : 'Due Date'}</div>
            <div className="due-date">{inKind
              ? (invoiceDate ? fmtDate(invoiceDate).toUpperCase() : '—')
              : (dueDate ? fmtDate(dueDate).toUpperCase() : 'TBD')}
            </div>
            {inKind && <div className="due-terms">No payment due</div>}
          </div>
        </div>

        {/* Talent / Campaign / Contract */}
        <div className="reference">
          <div>
            <div className="ref-label">Talent</div>
            {platformAccts.length > 0
              ? (
                <div className="talent-stack">
                  {platformAccts.map(acct => (
                    <div key={acct.platform} className="talent-row">
                      <span className={`platform-pill pill-${acct.platform?.toLowerCase()}`}>{acct.platform?.toUpperCase()}</span>
                      @{acct.username}
                    </div>
                  ))}
                </div>
              )
              : <div className="ref-value">{row.creator_name ? `@${row.creator_name.replace(/^@/, '').replace(/\s+/g, '').toLowerCase()}` : '—'}</div>
            }
          </div>
          <div>
            <div className="ref-label">Campaign</div>
            <div className="ref-value">{campaignName || '—'}</div>
          </div>
          <div>
            <div className="ref-label">Contract / PO</div>
            <div className="ref-value">{invoice?.po_number || '—'}</div>
          </div>
        </div>

        {/* Line items */}
        <table className="items">
          <thead>
            <tr>
              <th scope="col" className="col-desc">DESCRIPTION</th>
              <th scope="col" className="col-qty num">QTY</th>
              <th scope="col" className="col-rate num">{inKind ? 'FMV' : 'RATE'}</th>
              <th scope="col" className="col-amt num">{inKind ? 'FMV' : 'AMOUNT'}</th>
            </tr>
          </thead>
          <tbody>
            {lineItems.map((item, i) => (
              <tr key={i}>
                <td>
                  <div className="item-title">
                    <span className={`platform-pill pill-${item.platform?.toLowerCase()}`}>{item.platform?.toUpperCase()}</span>
                    {serviceDesc}
                  </div>
                  <div className="item-detail">{inKind && inKindDesc ? truncate(inKindDesc, 120) : fmtLineItemSub(item)}</div>
                </td>
                <td className="num">{inKind ? '—' : item.qty}</td>
                <td className="num">{i === 0 ? fmtMoney(amount) : '—'}</td>
                <td className="num item-amount">{i === 0 ? fmtMoney(amount) : '—'}</td>
              </tr>
            ))}
          </tbody>
        </table>

        {/* Totals */}
        <div className="totals">
          <div className="totals-table">
            <div className="totals-row total">
              <span className="label">{inKind ? 'Fair Market Value' : 'Total'}</span>
              <span className="value">{fmtMoney(amount)}</span>
            </div>
            {!inKind && amountPaid > 0 && (
              <div className="balance-due-bar">
                <span className="balance-due-label">BALANCE DUE</span>
                <span className="balance-due-value">{fmtMoney(balanceDue)}</span>
              </div>
            )}
          </div>
        </div>

        {/* Remit + Terms */}
        <div className="footer-grid">
          <div>
            {inKind ? (
              <>
                <div className="section-label">TAX DISCLOSURE</div>
                <div>
                  <div className="field-label">Compensation Type</div>
                  <div className="field-value bold">Non-cash (in kind)</div>
                </div>
                {inKindDesc && (
                  <div style={{ marginTop: 8 }}>
                    <div className="field-label">Items Received</div>
                    <div className="field-value">{truncate(inKindDesc, 200)}</div>
                  </div>
                )}
                <div style={{ marginTop: 8, fontSize: 11, color: 'var(--muted)', lineHeight: 1.5 }}>
                  No cash payment is due or expected. FMV is provided for tax reporting purposes only.
                </div>
              </>
            ) : (
              <>
                <div className="section-label">REMIT PAYMENT TO</div>
                <div>
                  <div className="field-label">Payable To</div>
                  <div className="field-value bold">{fromName}</div>
                </div>
                <div className="remit-grid">
                  {paypalLine && (
                    <div>
                      <div className="field-label">{paypalLabel2}</div>
                      <div className="field-value">{paypalLine}</div>
                    </div>
                  )}
                  {achLines && (
                    <div>
                      <div className="field-label">{otherMethodLabel2 || 'ACH / Wire'}</div>
                      {achLines.split('\n').map((l, i) => (
                        <div key={i} className="field-value" style={{ whiteSpace: 'nowrap' }}>{l}</div>
                      ))}
                    </div>
                  )}
                </div>
              </>
            )}
          </div>
          <div>
            <div className="section-label">{inKind ? 'IN-KIND TERMS' : 'TERMS'}</div>
            <ul className="terms-list">
              {termLines.map((l, i) => <li key={i}>{l}</li>)}
            </ul>
          </div>
        </div>

      </div>

      {/* Footer */}
      <div className="footer-band">
        <div className="footer-left">
          <div className="name">{fromName.toUpperCase()}</div>
          <div className="contact">{websiteDisplay}{sender?.email ? `  ·  ${sender.email}` : ''}</div>
        </div>
        <div className="footer-right">
          <div className="thanks">{inKind ? 'TAX RECORD' : 'THANK YOU'}</div>
          <div className="invoice-no">{inKind ? `In-Kind Record${invoice?.invoice_number ? ` ${invoiceNumber}` : ''}` : `Invoice ${invoiceNumber}`}</div>
        </div>
      </div>

    </div>
  );
}
